<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('catalog_categories.view');
$pageTitle='Categorías del catálogo';
$rows=db()->query('SELECT c.*,COUNT(sc.id) service_count FROM service_categories c LEFT JOIN service_catalog sc ON sc.category_id=c.id GROUP BY c.id ORDER BY c.sort_order,c.name')->fetchAll();
require __DIR__.'/includes/header.php';
?>
<section class="panel"><div class="panel-header"><div><h2>Categorías de productos y servicios</h2><span class="table-sub">Las categorías organizan los productos y servicios que aparecen al preparar una cotización.</span></div><?php if(has_permission('catalog_categories.manage')):?><a class="btn btn-primary" href="service_category_form.php">+ CREAR CATEGORÍA</a><?php endif;?></div><div class="table-wrap"><?php if(!$rows):?><div class="empty">Todavía no existen categorías.</div><?php else:?><table class="data-table"><thead><tr><th>Orden</th><th>Categoría</th><th>Descripción</th><th>Ítems</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as$row):?><tr><td><?=(int)$row['sort_order']?></td><td><strong><?=e($row['name'])?></strong></td><td><?=e($row['description']?:'—')?></td><td><?=(int)$row['service_count']?></td><td><span class="badge badge-<?=$row['is_active']?'green':'gray'?>"><?=$row['is_active']?'Activa':'Inactiva'?></span></td><td><?php if(has_permission('catalog_categories.manage')):?><div class="actions"><a class="btn btn-light btn-small" href="service_category_form.php?id=<?=(int)$row['id']?>">Editar</a><form method="post" action="service_category_toggle.php"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="btn btn-small <?=$row['is_active']?'btn-danger':'btn-success'?>" data-confirm="¿Confirmar el cambio de estado?"><?=$row['is_active']?'Desactivar':'Activar'?></button></form><form method="post" action="service_category_delete.php"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="btn btn-danger btn-small" data-confirm="¿ELIMINAR esta categoría? Los productos y servicios asociados quedarán como Sin categoría.">Eliminar</button></form></div><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section>
<?php require __DIR__.'/includes/footer.php';?>
